/// A simple interval type holding a start and end point.
#[derive(Debug, Clone, PartialEq)]
pub struct Interval {
    pub start: f32,
    pub end: f32,
}

/// A Laguerre series represented by its coefficients and two intervals:
/// the `domain` and the `window`.
#[derive(Debug, Clone, PartialEq)]
pub struct Laguerre {
    pub coefficients: Vec<f32>,
    pub domain: Interval,
    pub window: Interval,
}

/// Constructs a Laguerre series from the given floating‐point coefficients.
/// The `domain` and `window` are both set to the unit interval [0.0, 1.0].
///
/// Postcondition:
/// For every valid index `i` in `0..coefficients.len()`,
/// `output.coefficients[i] == coefficients[i]`.
pub fn make_laguerre(coefficients: Vec<f32>) -> Laguerre {
    let unit_interval = Interval { start: 0.0, end: 1.0 };
    Laguerre {
        coefficients,
        domain: unit_interval.clone(),
        window: unit_interval,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_make_laguerre_empty() {
        let coeffs: Vec<f32> = Vec::new();
        let L = make_laguerre(coeffs.clone());
        assert_eq!(L.coefficients, coeffs);
        assert_eq!(L.domain, Interval { start: 0.0, end: 1.0 });
        assert_eq!(L.window, Interval { start: 0.0, end: 1.0 });
    }

    #[test]
    fn test_make_laguerre_nonempty() {
        let coeffs = vec![3.14, -2.71, 0.0, 42.0];
        let L = make_laguerre(coeffs.clone());
        assert_eq!(L.coefficients, coeffs);
        assert_eq!(L.domain, Interval { start: 0.0, end: 1.0 });
        assert_eq!(L.window, Interval { start: 0.0, end: 1.0 });
    }
}